# fzf theme — Generated by theme system (do not edit)
#
# Sourced by ~/.zshrc and by dclean. Exporting FZF_DEFAULT_OPTS means every fzf
# invocation (Ctrl-R, Ctrl-T, dclean, lazygit pickers) picks up the palette.

export FZF_DEFAULT_OPTS="
--color=bg:#1a1a2e,bg+:#2a2a40
--color=fg:#b4a7d6,fg+:#e0e1e5
--color=hl:#00ff88,hl+:#00ff88
--color=info:#8844ff,spinner:#8844ff
--color=prompt:#00aaff,pointer:#ff44aa
--color=marker:#00ff88,header:#b4a7d6
--color=border:#8844ff,label:#00aaff
--color=query:#e0e1e5,disabled:#2a2a40
--color=gutter:#1a1a2e,separator:#2a2a40
--color=scrollbar:#8844ff,preview-border:#2a2a40
--color=preview-label:#00ff88
--prompt='▸ '
--marker='◉ '
--pointer='▶'
--cycle
"
